select has_function_privilege('postgres','essay_private.clock()','EXECUTE') server_clock_access, not pg_has_role('postgres','essay_executor','SET') role_restored, not has_function_privilege('authenticated','essay_private.clock()','EXECUTE') client_blocked, not has_function_privilege('anon','essay_private.clock()','EXECUTE') anon_blocked, not exists(select 1 from essay_beta_private.campaigns where enabled) campaign_inactive;
